"""Serialize manually authored concordances. No classification is inferred from text."""
import csv,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
ITEMS=[]; ENTRIES=[]
P=['MPL_60_002-035','MPL_60_036-070']
def add(n,title,kind,loc,words,statement,reconstruction,check,reason,rows,attribution='handwritten mathematical text'):
    sources=[]
    for package,entry,verdict,why in rows:
        eid=f'{P[package-1]}#{entry}'; sources.append(eid)
        ENTRIES.append(dict(entry_id=eid,item_id=f'SA14-{n}',verdict=verdict,reason=why))
    ITEMS.append(dict(id=f'SA14-{n}',sources=sources,kind=kind,cote=60,scans=loc[0],lines=loc[1],his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason,title=title,attribution=attribution))
add(401,'Characteristic polynomial and exterior traces','other',([3],['MPL_60_002-035_transcription.tex:9–19']),r'P_f(t)=det(1-ft)',
'For an endomorphism of a finite-dimensional vector space, the coefficient of t^i in det(1-tf) is (-1)^i Tr(Λ^i f).','No extra hypothesis on diagonalizability is needed.','agrees','The displayed expansion is a finite determinant identity.',[(1,1,'kept','The determinant and exterior-power trace expansion is explicitly present at 60:3, lines9–19; no semisimplicity assumption occurs.')])
add(402,'Symmetric traces and exact-sequence multiplicativity','other',([3],['MPL_60_002-035_transcription.tex:20–29']),r'Z_f(t)=P_f(t)^{-1}',
'The reciprocal determinant is Σ Tr(Sym^ν f)t^ν; a stable subspace gives multiplicativity of P and L along the induced short exact sequence.','The symmetric-power identity is a formal-series identity; its rationality here follows from finite-dimensionality.','agrees','Both formulas are displayed on scan3.',[(1,2,'kept','Scan3 lines20–29 gives both the symmetric-power series and the short-exact-sequence formula; the note correctly separates their roles.')])
add(403,'Tensor product and rational Witt multiplication','unpursued implication',([3,5],['MPL_60_002-035_transcription.tex:30–32,92–102']),r'(1-at)*(1-bt)=1-abt',
'On rational characteristic functions with constant coefficient1, ordinary multiplication represents direct sum, while the displayed star product represents tensor product. The rational Witt interpretation is a modern identification.','Use the splitting principle, or extend scalars to triangularize. This is not the assertion that all formal series represent finite-dimensional objects.','agrees','The factor rule is on the page; the name rational Witt belongs to the earlier run.',[(1,3,'kept','The star rule at3 and tensor formula at5 justify the rational Witt comparison; the missing star in the multifactor product remains an ink alarm.')])
add(404,'Reciprocal characteristic functions and signs','reading question',([5],['MPL_60_002-035_transcription.tex:92–126']),r'L_f(t)=P_f(t)^{-1}',
'If P is the characteristic-polynomial convention, L=P^{-1} represents its negative in the additive group of the Witt ring. Exterior and symmetric operations must be transported across this negation; an unqualified unchanged λ convention is unsafe.','A rank-one test determines the necessary convention. The transcription is not silently normalized.','agrees','The page changes to reciprocal L and reverses λ and σ in its final relation.',[(1,4,'kept','The note correctly distinguishes the reciprocal convention from the P convention; the surviving formula at125–126, not the cancelled one, governs the reading.')])
add(405,'Cancelled λ generating identity','withdrawn in the same text',([5],['MPL_60_002-035_transcription.tex:115–126']),r'\deleted{',
'The generating identity at115–119 is struck through; the surviving comparison at125–126 is the operative formulation.','No second theorem is extracted from cancelled material.','agrees','The supplied diplomatic markup explicitly records deletion.',[(1,5,'kept','The cancelled identity is retained as revision history and is not counted as an additional live theorem.')])
add(406,'Contragredient reciprocity and its domain','other',([7],['MPL_60_002-035_transcription.tex:163–186']),r'P_{\check f}(t)=(-t)^n det(f)^{-1}P_f(t^{-1})',
'For an invertible endomorphism f of dimension n, det(1-tf^{-1})=(-t)^n det(f)^{-1}det(1-t^{-1}f). Reciprocals give the L identity.','Inversion t↦t^{-1} is applied to rational functions, not arbitrary elements of 1+tK[[t]]. The boxed ε exponent means virtual rank if extended additively.','agrees','The elementary derivation is visible, with an intermediate sign uncertainty.',[(1,6,'kept','Scan7 supplies reciprocal determinants; the note correctly restricts the operation to rational functions and marks the intermediate sign as a reading issue.')])
add(407,'Three different epsilon conventions','reading question',([7,9,27,31,53,57],['MPL_60_002-035_transcription.tex:180,216–243,736–766,842–855','MPL_60_036-070_transcription.tex:363–404,493–520']),r'\varepsilon',
'The rank-like ε in the early reciprocity box, the normalized determinant δq^{-χ/2}, and the signed FE multiplier (-1)^χδq^{-χ/2} are distinct. Nonproper normalized determinants need not be signs.','The labels ε_rank, ε_c and ε_FE are editorial notation only. They are not new manuscript symbols.','agrees','The same letter changes role; A¹ and G_m separate the possible meanings.',[(1,7,'kept','The early exponent and later determinant normalization are textually different uses of ε.'),(1,51,'merged','The later note refines the same convention issue by separating ε_c from (-1)^χ ε_c, as scan31 does.'),(2,49,'merged','The context note repeats the epsilon warning; its further project comparisons are quarantined, while the cote60 meanings are directly checked.')])
add(408,'Determinant sign needs rationality or selfduality','unproved claim',([9],['MPL_60_002-035_transcription.tex:216–243']),r'det F=\varepsilon p^{n\rho/2}',
'For a pure object of weight ρ with rational characteristic polynomial, its determinant is real and has absolute value p^{nρ/2}, hence is ±p^{nρ/2}. Purity of an arbitrary ℓ-adic sheaf alone does not make the determinant real.','The countermodel F=ζ₃ on a one-dimensional ℓ-adic representation of Gal(F̄_p/F_p), ℓ=7 and p≠7, is weight0 and violates the sign assertion. It does not refute the rational motivic context.','agrees','The page first mentions a sheaf and then returns to a pure motive; the note properly warns against forgetting that scope.',[(1,8,'kept','The determinant formula is present, but the text changes from a sheaf to a pure motive; the note’s scope counterexample applies only after removing the rational motivic hypothesis.')])
add(409,'Odd weight and even rank','unproved claim',([9],['MPL_60_002-035_transcription.tex:221–230']),r'n\rho/2\in\mathbb Z',
'For p prime and a rational characteristic polynomial pure of integral weight ρ, rationality of detF=±p^{nρ/2} implies nρ even. This implication differs from positivity of the determinant.','A one-dimensional continuous Q₇-representation with F=√2, p=2, has odd weight1 and odd rank; √2 belongs to Q₇. It lacks rational characteristic polynomial.','agrees','The integrality assertion needs the surrounding rationality; the note distinguishes it from polarization.',[(1,9,'kept','The parity inference at9 is valid under rationality; it does not establish the separate positive-sign assertion of17.')])
add(410,'Selfdual coefficient comparison','unproved claim',([9,13,53],['MPL_60_002-035_transcription.tex:231–243,370–381','MPL_60_036-070_transcription.tex:381–402']),r'\check E\simeq E(\rho)',
'A Frobenius-equivariant perfect pairing E⊗E→Q_ℓ(-ρ) identifies E^∨ with E(ρ). Purity, even with prescribed eigenvalue absolute values, does not by itself give this pairing.','The later reference to a selfdual pure motive is treated as an additional hypothesis; no general selfduality of lisse sheaves is supplied.','agrees','The coefficient comparison is admitted on13 and reused on53.',[(1,10,'kept','The note matches the admission on13 and correctly treats “par Lefschetz” on9 as extra input about the chosen coefficient object.'),(2,9,'merged','The “poids … donc” step on53 repeats the same missing selfduality hypothesis; the two locations are merged rather than counted as independent theorems.')])
add(411,'Tate twist and variable substitution','other',([9],['MPL_60_002-035_transcription.tex:234–243']),r'L_E(t/p^\rho)',
'With geometric Frobenius acting on Q_ℓ(1) by p^{-1}, L_{E(r)}(t)=L_E(p^{-r}t).','At a closed point of degree d, replace p by p^d and use t^d in the global Euler factor.','agrees','The variable change fixes the convention used in the later sign checks.',[(1,11,'kept','The twist substitution is explicitly displayed on9; it supplies the convention against which scans15 and53 are tested.')])
add(412,'Properness inserted; nonproper correction added later','withdrawn in the same text',([11,19,21],['MPL_60_002-035_transcription.tex:295–310,511–532,561–591']),r'\deleted{compactifiable}\inserted{propre}',
'The uncorrected proper functional equation is asserted after replacing compactifiable by proper. Nonproper separated finite-type schemes are handled later using compact/ordinary comparison and a boundary factor.','This is a visible correction of scope, not evidence that compactification itself fails.','agrees','The deletion and later boundary calculations are both supplied.',[(1,12,'kept','The note correctly follows the inserted properness at11 to its nonproper replacement at19–21.')])
add(413,'Derived determinant reciprocity: the two-object equation','other',([11,17],['MPL_60_002-035_transcription.tex:310–320,480–483']),r'L_{D E}(t)=(-t)^{-\chi(E)}\delta(E)L_E(t^{-1})',
'For a bounded finite-dimensional Frobenius complex C with invertible F, χ(C)=Σ(-1)^i dimH^i(C) and δ(C)=∏det(F|H^i)^{(-1)^i}; degreewise reciprocal determinants give L_{C^∨}(t)=(-t)^{-χ(C)}δ(C)L_C(t^{-1}). Proper duality transfers this to X.','A self-equation for one object additionally requires the coefficient pairing. General Verdier duality exchanges the two objects.','agrees','The formula follows the surviving derived expression on11 and the reminder on17.',[(1,13,'kept','The note reads χ and δ in the surviving derived formula, and its degreewise proof uses the already established7 reciprocity.'),(1,25,'merged','The late two-object warning is exactly the scope of this same duality formula, before adding a selfdual coefficient identification.')])
add(414,'Cohomological weights are extra input','unproved claim',([11,13],['MPL_60_002-035_transcription.tex:316–320,347–369']),r'avec les conjectures',
'For smooth proper X/F_p of pure dimension n and pure lisse E of weightρ, the weight calculation for H^i requires the cohomological purity theorem, and the rational sign needs an appropriate rational/selfdual structure.','Today the weight theorem is supplied by Deligne; this does not supply every standard-conjecture polarization claimed in a motivic reading.','agrees','The manuscript marks the conjectural qualification rather than proving the weight theorem.',[(1,14,'kept','The explicit qualification at11 must accompany the numerical substitution on13; the note correctly separates it from formal determinant reciprocity.')])
add(415,'Betti symmetry and weighted Euler sum','unproved claim',([13],['MPL_60_002-035_transcription.tex:347–369']),r'\sum(-1)^i i b_i=n\chi',
'For a smooth proper n-fold and a lisse coefficient object selfdual with twistρ, Poincaré duality gives b_i=b_{2n-i}. Therefore Σ(-1)^i i b_i=nχ, and purity gives |δ|=p^{(n+ρ)χ/2}.','The symmetry needs the same coefficient object on both sides; without selfduality duality compares E and E^∨ instead.','agrees','The sum is explicitly computed using the displayed pairing of degrees.',[(1,15,'kept','Scan13’s numerical identity is valid with the preceding selfdual coefficient comparison; the note supplies the needed scope without changing the page.')])
add(416,'Generic-point extension of a lisse isomorphism','self-flagged step',([13],['MPL_60_002-035_transcription.tex:370–381']),r'point générique',
'On an integral normal scheme, restriction of lisse ℓ-adic sheaves to the generic point is fully faithful: an existing generic isomorphism extends. This does not produce a selfduality isomorphism merely from purity.','This is the strongest valid reading of the small generic-point remark. The uncertain abbreviated sentence is not completed from conjectural intent.','agrees','The note limits the conclusion to extension rather than existence.',[(1,16,'kept','The generic-point remark can justify extending a given lisse comparison on normal X; it cannot establish the comparison’s existence.')])
add(417,'Derived shifts versus Grothendieck classes','reading question',([13,33,49],['MPL_60_002-035_transcription.tex:379–390,880–896','MPL_60_036-070_transcription.tex:233–266']),r'DE=E(n+\rho)[2n]',
'For smooth n-dimensional X, D_XE=E^∨(n)[2n]. Even shifts disappear from K₀ and L-functions but remain essential to an isomorphism of complexes. For a curve, underived middle extension j_*E satisfies D_X(j_*E)≃j_*E^∨(1)[2].','The virtual extension on49 is a K₀ class; it supplies no canonical derived object or derived lift of averaging.','agrees','The supplied text both writes and deletes shifts in different categorical contexts.',[(1,17,'kept','The even shift is explicit on13; the note correctly prevents its loss at the level of complexes.'),(2,6,'merged','The deleted [2] on49 is harmless in K₀, but the virtual construction is not a canonical object.'),(2,48,'merged','The context warning about brackets is retained as a comparison, with its cote60 side checked and its other-project side quarantined.')])
add(418,'Half powers in normalized functional equations','reading question',([15,35,53,63],['MPL_60_002-035_transcription.tex:423–435,940–947','MPL_60_036-070_transcription.tex:363–404,593–624']),r'\xi(t)=t^{\chi/2}L(t)',
'When χ is odd, the normalized ξ lives naturally on a square-root coordinate u with t=u², or in a chosen quadratic extension of the rational-function field. A choice of p^{1/2} likewise requires a coefficient extension.','The actual L-function remains rational in t. The half-power normalization is an editorially explicit extension of the coefficient setting.','agrees','No parity condition on χ is supplied that would always remove the half power.',[(1,18,'kept','The formula on15 has χ/2 and χ can be odd, as P² shows.'),(2,22,'merged','The later normalization repeats the same coefficient-field and half-weight issue; it does not resolve it by choosing a field.')])
add(419,'Tate target in the Poincaré pairing','reading question',([15],['MPL_60_002-035_transcription.tex:438–445']),r'\mathbf Q_\ell(n)',
'Under geometric Frobenius, the untwisted Poincaré trace H^{2n}(X̄,Q_ℓ)→Q_ℓ(-n) has target Q_ℓ(-n). The transcribed +n target conflicts with the convention on9.','Mathematics raises the alternative -n; only scans can establish the ink.','agrees','The note identifies a genuine sign conflict rather than changing the source.',[(1,19,'kept','The target on15 has the opposite twist from the geometric-Frobenius convention fixed by9; this remains an undecided ink alarm.')])
add(420,'Middle-degree determinant sign','unpursued implication',([15,17],['MPL_60_002-035_transcription.tex:438–445,473–483']),r'\chi\equiv b_n\pmod2',
'Selfdual degree pairs contribute squares after normalizing eigenvalues, so the remaining determinant sign is controlled by middle cohomology; χ≡b_n mod2.','A positive pairing sign or orthogonal/symplectic type must be stated when extracting a numerical root sign.','agrees','The parity and middle-degree reduction are on the page.',[(1,20,'kept','The reduction to b_n is explicitly supported by the degree pairing; it is not a separate parity conjecture.')])
add(421,'Odd-weight determinant positivity needs an alternating pairing','unproved claim',([17],['MPL_60_002-035_transcription.tex:473–483']),r'\varepsilon=+1',
'A q-similitude of a nondegenerate alternating form in dimension2m has determinant q^m. A symmetric pairing with the same odd weight does not force the plus sign.','For F=[[0,p],[1,0]], B=diag(1,p), FᵀBF=pB and detF=-p. This refutes only the unqualified symmetric/selfdual generalization, not a polarized odd-weight motive.','agrees','The note correctly makes polarization the extra input and labels the matrix as a scope counterexample.',[(1,21,'kept','The positivity assertion on17 requires the alternating polarization appropriate to the intended odd-weight object.'),(1,22,'merged','The 2×2 symmetric countermodel tests precisely that omitted hypothesis and does not contradict the polarized formulation.')])
add(422,'Normalized Frobenius and central poles','reading question',([17],['MPL_60_002-035_transcription.tex:473–483']),r'\varepsilon\prime=(-1)^{e_1}',
'The ±1 eigenspaces must be those of F₀=p^{-(n+ρ)/2}F on middle cohomology. For P², the middle eigenvalue is p, normalized to1, and the center t=p^{-1} is a pole of L. Thus a negative FE sign constrains order parity, not necessarily a zero.','The P² test is a reconstruction testing the sign convention. No “central zero” conclusion is present in the manuscript.','agrees','The note retains the overwritten multiplicity wording and correctly identifies the normalization.',[(1,23,'kept','Raw eigenvalues cannot generally be ±1; normalization is forced by the weight on the same page.'),(1,24,'merged','The P² calculation is a concrete test of that same normalized-eigenvalue issue and of order rather than zero parity.')])
add(423,'Boundary cone and the one-unit duality shift','self-flagged step',([19,25,61],['MPL_60_002-035_transcription.tex:511–532,665–698','MPL_60_036-070_transcription.tex:554–578']),r'à vérifier si 1 ou -1!',
'Define C∞(E)=Cone(RΓ_c(E)→RΓ(E)). Duality gives D C∞(E)≃C∞(DE)[-1]. For smooth n-fold and E^∨≃E(ρ), this becomes C∞(E)^∨≃C∞(E)(n+ρ)[2n-1].','The source initially writes R_*−R_! virtually; scan61 supplies cone data. With the fiber convention all shifts change coherently. Both ±1 have the same K₀ parity, so L cannot decide the question.','agrees','The self-flagged sign on25 is determined only after selecting the cone convention made explicit on61.',[(1,26,'kept','The difference on19 is represented by the natural compact-to-ordinary cone, as61 later spells out.'),(1,31,'merged','The explicit “1 ou -1” question on25 belongs to the same boundary object; the cone convention yields -1.'),(2,17,'merged','The long exact sequence and compactification triangle on61 identify the boundary construction and expose the i+1 grading alternative.'),(2,57,'merged','This additional note gives the same cone-duality derivation, so it does not define a second boundary problem.')])
add(424,'Formal nonproper functional equation','unproved claim',([19,21],['MPL_60_002-035_transcription.tex:511–532,561–591']),r'A(t)=L_\infty(1/(qt))^{-1}',
'For smooth separated finite-type X/F_p, pure dimensionn, lisse selfdual E with twistρ, put q=p^{n+ρ}. Duality and determinants give L_c(1/(qt))=A(t)δ_c(-t)^χ_c L_c(t).','The formal identity requires the six-functor duality and finiteness, not resolution or weight-purity assertions. The page’s additional motivic/type claims are separate.','agrees','The note correctly disentangles the formal calculation from the qualification written in the margin.',[(1,27,'kept','The boundary correction formula is formal once the stated duality holds; the resolution/Weil qualification concerns the stronger weight/type discussion.')])
add(425,'Boundary type and weight bound','self-flagged step',([21],['MPL_60_002-035_transcription.tex:561–579']),r'type\leq\tau+n-1',
'The text proposes a bound on the “type” and weight of the boundary object under resolution/Weil assumptions. No definition of type sufficient to identify its quantifiers is supplied.','Modern weight bounds for mixed ℓ-adic complexes are nearby results; they do not identify this undefined motivic type invariant.','agrees','The note declines to substitute a modern invariant for the undefined type.',[(1,28,'kept','The type and weight line is retained as an authorial problem, but the exact type predicate cannot be recovered from this packet.')])
add(426,'Compact and ordinary Euler characteristics','other',([21,27],['MPL_60_002-035_transcription.tex:580–591,736–766']),r'\chi_!=\chi_*',
'Under the same selfdual coefficient comparison, compact and ordinary cohomology have dual Betti numbers in degreesi and2n−i, hence χ_c=χ_* and δ_cδ_*=q^χ. Therefore χ∞=0.','The corresponding equality for arbitrary sheaves is not deduced merely by erasing the dual coefficient.','agrees','The Euler and determinant statements are the displayed consequences of duality.',[(1,29,'kept','The note correctly ties the equality to the explicit selfdual coefficient hypothesis rather than to finiteness alone.')])
add(427,'Virtual weights and weighted counts','reading question',([23],['MPL_60_002-035_transcription.tex:617–636']),r'h_!^i',
'The h_!^i and β_i on23 organize virtual pieces by pure weight. Their alternating multiplicities are not automatically the cohomological Betti numbers of RΓ_c.','A weighted-count comparison with an earlier packet is only a lead; that packet is not supplied.','agrees','The notation and deletions distinguish this virtual weight decomposition from the earlier degreewise formula.',[(1,30,'kept','The note correctly prevents conflating weight indexing on23 with cohomological indexing on13.'),(1,58,'merged','The earlier-run weighted-count analogy concerns the same virtual weight calculation; its external endpoint remains unchecked.')])
add(428,'Deleted boundary square','withdrawn in the same text',([25],['MPL_60_002-035_transcription.tex:683–698']),r'\deleted{',
'The putative boundary square is crossed out, and the dual object is inserted in the replacement. A relation between boundary functions and their duals survives; it is not an unconditional square identity.','The source’s revision is preserved separately from any normalization chosen later.','agrees','Deletion and insertion are explicit in the diplomatic text.',[(1,32,'kept','The note follows the crossed-out square to the dual-object replacement; the deleted version is not counted as a live assertion.')])
add(429,'Reciprocal normalized determinants; A¹ and G_m checks','reading question',([27],['MPL_60_002-035_transcription.tex:736–766']),r'\delta_!q^{-\chi/2}=\delta_*q^{-\chi/2}',
'The correct consequence of δ_cδ_*=q^χ is ε_c=δ_cq^{-χ/2}=(δ_*q^{-χ/2})^{-1}. For A¹, δ_c=p, δ_*=1, χ=1; for G_m, δ_c=p, δ_*=p^{-1}, χ=0. These normalized determinants need not be ±1.','The displayed equality on27 conflicts with the preceding product. Its reciprocal alternative is an ink alarm; the examples are independent reconstructions.','agrees','The notes’ examples directly test the displayed normalization and boundary function.',[(1,33,'kept','The two normalized determinants must be reciprocal by line760; line761 as transcribed is incompatible with A¹.'),(1,34,'merged','The affine-line example is a concrete verification of the same normalization and its boundary A(t).'),(1,35,'merged','The G_m example adds two boundary points and gives ε_c=p, confirming that nonproper ε is not merely a sign.')])
add(430,'Applying the involution twice','other',([29,63],['MPL_60_002-035_transcription.tex:791–823','MPL_60_036-070_transcription.tex:593–624']),r'B(t)B(1/(qt))=1',
'For σ(t)=1/(qt), a ratio B=σL/L has norm Bσ(B)=1. In the boundary formula this imposes the specific scalar norm on A after including δ_c(-t)^χ.','This is a consistency condition; it does not construct geometric coefficients or solve the restricted lower-niveau problem.','agrees','The involution calculation is explicitly performed and later abstracted.',[(1,36,'kept','The twice-applied functional equation gives a necessary consistency relation, not a separate existence theorem.'),(1,52,'merged','The later note identifies the same relation for the boundary factor A with its normalization constants.'),(2,18,'merged','Scan63 recasts that same involution relation as a rational-function cocycle equation.')])
add(431,'Variation with coefficients, scheme and base field','self-flagged step',([27],['MPL_60_002-035_transcription.tex:758–766']),r'E,X!!',
'The marginal variation question includes E and X. Under the concrete operation F_p→F_{p^r}, Frobenius becomes F^r, χ is unchanged, δ becomes δ^r, and a consistently chosen normalized ε becomes ε^r.','This base-field test is our partial answer; the full dependence on E and X is the author’s broader question. L_{F^r}(t) is not generally L_F(t^r).','agrees','The margin asks a broader question than the example developed in the note.',[(1,37,'kept','The note labels finite-field extension as a test of the explicit variation question, and does not claim to settle arbitrary variation in E or X.')])
add(432,'Extra mark on A in normalized box','reading question',([31],['MPL_60_002-035_transcription.tex:842–855']),r'A^\xi',
'The normalized box includes an extra mark on A whose mathematical role is not defined. The surrounding derivation requires the already defined boundary factor, with the t↔1/(qt) convention fixed.','No choice of superscript or deletion is made without scans.','agrees','The ambiguity is present in the transcription and cannot be settled by the later identities alone.',[(1,38,'kept','The unexplained mark is a genuine reading question; the note correctly refuses to manufacture a new operation.')])
add(433,'Function fields, smooth proper curves and coefficient finiteness','other',([33],['MPL_60_002-035_transcription.tex:880–891']),r'K détermine X',
'A one-variable function field over a perfect field determines its smooth projective curve. For an ℓ-adic representation at its generic point to define a constructible extension, require it to be lisse on some dense open (in particular finitely ramified).','The phrase constructible at the generic point alone does not encode finite ramification on the curve.','agrees','The curve reconstruction is explicit; the coefficient finiteness is a necessary scope qualification.',[(1,39,'kept','The note separates the standard function-field/curve equivalence from the extra finite-ramification requirement for coefficients.')])
add(434,'Middle extension and the curve functional equation','other',([33],['MPL_60_002-035_transcription.tex:884–912']),r'D(i_*E)=i_*\check E(1)',
'For a lisse sheaf on a dense open of a smooth proper curve, j_*E[1] is the intersection complex; duality gives D(j_*E)=j_*E^∨(1)[2]. Its L-equation, after substituting t↔1/(qt), has the positive χ exponent written at896.','Dropping [2] is legitimate in K₀/L but not as a literal derived isomorphism. The generic map i must be interpreted through an open of lissity.','agrees','The note correctly distinguishes the harmless even shift at class level from the sign of χ in the transformed equation.',[(1,40,'kept','The underived extension has middle-extension duality on a curve, with the missing [2] restored only in the explanatory reconstruction.'),(1,41,'merged','The positive Euler exponent is the same equation after inversion; it is not an additional sign error.')])
add(435,'Failure of exact invariants and the correction sheaf Q','self-flagged step',([35,37],['MPL_60_002-035_transcription.tex:950–977','MPL_60_036-070_transcription.tex:20']),r'Q=Coker(i_*E\to i_*E\prime\prime)',
'For 0→E′→E→E″→0 on a dense open of a curve, underived direct image yields a finite-support cokernel Q. In K₀, [j_*E]=[j_*E′]+[j_*E″]−[Q], so L(E)=L(E′)L(E″)/L(Q), χ(E)=χ(E′)+χ(E″)−χ(Q), and similarly δ is divided by δ(Q). Q may be nonzero where E″ is unramified.','A tame unipotent extension of unramified characters gives this support counterexample; it is mixed, so it does not refute exactness for geometrically semisimple pure coefficients. The crossed-out R¹ kernel remains a correct connecting-map description.','agrees','The note accurately reads the nonexactness, detects the support overstatement, and distinguishes the pure category.',[(1,42,'kept','The multiplicative direction on35 follows from the four-term exact sequence with Q subtracted.'),(1,43,'merged','The support assertion “ramification of E″” is too narrow; a nontrivial unipotent middle representation with unramified endpoints is a checked counterexample.'),(1,44,'merged','The Kummer extension on G_m globalizes that same local counterexample and produces the finite correction factors at0 and∞.'),(1,45,'merged','The note’s purity qualification correctly excludes this mixed extension from the geometrically semisimple pure case.'),(1,46,'merged','The deleted R¹-kernel expression is the same Q via the connecting map, not a separate obstruction object.'),(1,53,'merged','The same K₀ correction simultaneously changes χ and δ; its defect is not confined to L.')])
add(436,'Residue degrees in Euler factors and local determinants','reading question',([35,55,57],['MPL_60_002-035_transcription.tex:969–977','MPL_60_036-070_transcription.tex:431–456,493–520']),r'\prod_x P_{Q(x)}',
'For x of degree d over F_p, a local Frobenius polynomial P_x contributes P_x(t^d). Induction to F_p gives det(1-t IndF_x)=det(1-t^d F_x), with determinant sign (-1)^{(d-1)rank}.','The local δ_x conventions must state whether they refer to F_x or its induced base-field representation.','agrees','The formulas omit explicit degree notation; the note correctly makes the convention visible.',[(1,47,'kept','The finite-support correction on35 requires t^{deg x} unless its notation already incorporates induction.'),(2,12,'merged','The later local determinant/product calculations use the same residue-degree convention; the induced determinant sign is part of this common issue.')])
add(437,'Final H² marginal comparison','reading question',([35],['MPL_60_002-035_transcription.tex:974–977']),r'H^2',
'On a smooth proper curve with E^∨≃E(ρ), H²(E) is dual to H⁰(E) with the corresponding twistρ+1. The marginal line is cohomological duality data.','It contains no new height pairing or positivity theorem. The incomplete wording is not expanded beyond this compatibility.','agrees','The surrounding curve FE fixes the mathematical role of H².',[(1,48,'kept','The note correctly places the marginal H² line in curve duality and rejects a height-theory inference unsupported by the page.')])
add(438,'From global determinants to Euler products','unproved claim',([11,33,35],['MPL_60_002-035_transcription.tex:310–320,880–912,969–977']),r'L(X,E)',
'The equality of the global alternating cohomological determinant with the closed-point Euler product is the Grothendieck trace formula; it is not a consequence of the elementary determinant identity alone.','This is a required theorem when the same L notation is interpreted both ways.','agrees','The manuscript uses the bridge without proving it in this packet.',[(1,49,'kept','The note identifies the precise trace-formula input needed to move from cohomological determinants to the local factors used later.')])
add(439,'Deleted χ as a virtual object','withdrawn in the same text',([11],['MPL_60_002-035_transcription.tex:298–308']),r'\chi',
'The deleted formulas use χ in a virtual-object sense before the surviving text defines the scalar Euler characteristic and δ separately.','Do not substitute the later integer χ into the erased functorial object expression.','agrees','The cancellation and change of role are visible.',[(1,50,'kept','The note correctly reads the cancelled χ formula as virtual cohomology, rather than treating it as the later rank integer.')])
add(440,'“Constant tordu” contextual expansion','reading question',([9,33],['MPL_60_002-035_transcription.tex:216–243,880–912']),r'constant tordu',
'The phrase can describe a geometrically constant sheaf with arithmetic Frobenius action; the relevant operation is its Frobenius representation and Tate twists.','This is a contextual gloss, not an ink emendation and not a new universal construction.','agrees','The note explicitly labels its expansion as contextual.',[(1,54,'kept','The explanatory expansion does not alter the transcribed phrase and is limited to the finite-field coefficient setting.')])
add(441,'Generic direct image and constructibility','idea of the earlier run',([35],['MPL_60_002-035_transcription.tex:950–977']),r'R^1i_*',
'For the generic-point inclusion, R¹i_*Q_ℓ has nonzero inertia cohomology at every closed point and is not a constructible sheaf on the whole curve. For a fixed dense open j, Rj_* of a constructible complex is the appropriate finite-type construction.','The counterexample is our/earlier-run scope check; the author’s deleted kernel formula may still be used locally.','agrees','The note distinguishes the literal generic map from a fixed open immersion.',[(1,55,'kept','The note prevents upgrading the deleted R¹ kernel into an unqualified global constructible complex; the constant generic sheaf already exposes the issue.')])
add(442,'Context register: no theorem update without its other endpoint','idea of the earlier run',([9,13,33,53,55],['MPL_60_002-035_transcription.tex:216–243,347–390,880–912','MPL_60_036-070_transcription.tex:363–456']),r'motif',
'The packet uses motives and ℓ-adic realizations, but does not construct the sought motivic category, prove a height theorem, identify standard-conjecture letter conventions, or verify the named LM/S6/Derivateurs result-register claims.','These entries are retained only as earlier-run contextual leads. The named external cotes/runs are not supplied and both-endpoint verification is unavailable.','agrees','The entries themselves mostly make negative or limited-scope comparisons; no external assertion is promoted into manuscript mathematics.',[(1,56,'kept','C01 is a usage witness for motivic language, not the construction requested in the external planning questions.'),(1,62,'merged','C07 explicitly reports no height-programme resolution; the cote60 passage contains FE duality, not the cited height argument.'),(1,63,'merged','C08 supplies no A–D dictionary in the actual text, so its comparison stays a negative contextual lead.'),(1,65,'merged','C10 carries earlier register statuses forward without a new proof here; those statuses cannot be independently verified from this packet.'),(1,66,'merged','The scope entry is provenance for the same context register, including absent scans and external endpoints.'),(1,67,'merged','The context-search key is navigation, not another mathematical claim or verified endpoint.'),(1,68,'merged','The results-register table contains contextual cross-links; the actual FE pages do not check the register’s other arguments.'),(2,61,'merged','This table collects comparisons already represented individually; its unavailable project endpoints stay quarantined.'),(2,62,'merged','This table explicitly lists topics receiving no mathematical update; it cannot be treated as new proofs from cote60.')],attribution='earlier-run context commentary; no corresponding manuscript theorem')
add(443,'Numerical motives and semisimplicity','idea of the earlier run',([9,13],['MPL_60_002-035_transcription.tex:216–243,347–390']),r'motif',
'Jannsen’s theorem identifies numerical equivalence as the adequate relation giving a semisimple abelian category of pure motives with characteristic-zero coefficients. It does not construct a mixed motivic category or prove equality of numerical and a chosen homological equivalence.','This is a checked published comparison, not a theorem stated on the manuscript page.','agrees','The note carefully distinguishes the later theorem from the motivic assumptions used here.',[(1,57,'kept','The Jannsen comparison is mathematically relevant but supplies only pure numerical semisimplicity; the source passage merely invokes motives.')],attribution='earlier-run published comparison')
add(445,'Oda’s filtered de Rham comparison','idea of the earlier run',([],[]),'',
'For an abelian variety over a perfect field of characteristicp, Oda1969 Corollary5.11 identifies the Dieudonné module of its p-torsion with H¹_dR, carrying the indicated submodule to H⁰(Ω¹). Corollary5.12 has a more restricted smooth-proper Picard formulation.','The published endpoint is checked; the earlier project passage asking the question is not supplied. No identification with the characteristic-zero inertia averaging of39–47 is asserted.','not on the page','These notes discuss a distinct published answer to an external de Rham lead.',[(1,59,'kept','The note explicitly treats Oda as a published comparison to an earlier packet; it is not a theorem of the current FE sheets.'),(2,50,'merged','The later Oda note repeats that precise comparison and warns against identifying it with inertia averaging.')],attribution='earlier-run published comparison; external archive endpoint unavailable')
add(446,'Cartier/Dieudonné duality is not positivity','idea of the earlier run',([],[]),'',
'Oda’s finite-group duality transports Cartier duality to the appropriate Dieudonné dual. A symmetric homomorphism or a duality alone is not a positivity assertion for a polarization.','The two categories and their twist/variance conventions are kept separate from ℓ-adic contragredients. The external positivity problem remains unchecked.','not on the page','The relevant Cartier and positivity claims occur in the notes’ external context, not in these FE formulas.',[(1,60,'kept','The checked Oda comparison concerns Cartier duality with its Dieudonné operations, not a new statement written here.'),(2,51,'merged','The later caution concerns the same distinction and correctly refuses to infer positivity from a symmetric morphism.')],attribution='earlier-run published comparison; external archive endpoint unavailable')
add(447,'Finite-length PID duality and two rédaction strategies','other',([12,16,26],['MPL_60_002-035_transcription.tex:331–341,463–470,712–733']),r'Hom_A(E,K/A)',
'For a nonfield PID A with fraction fieldK, Hom_A(-,K/A) is exact on finite-length modules, preserves length, and the evaluation map to the bidual is an isomorphism. Orthogonals reverse sums/intersections. The reused pages contrast a direct cyclic-module proof with a separate injectivity treatment.','Noncanonical self-isomorphism E≃E^* must not be confused with canonical biduality. The Oda connection is a published comparison in a different category.','agrees','These are printed reused texts, explicitly distinguished from the handwritten FE argument.',[(1,61,'kept','The finite-length duality on12/16 is real; its use inside Oda is a comparison, not a new Grothendieck handwriting claim.'),(1,70,'merged','The reused PID and injective-module drafts cover the same duality mechanism with different rédaction strategies.')],attribution='reused printed Bourbaki algebra sheets, not the handwritten FE narrative')
add(449,'Rejected global semisimplification','withdrawn in the same text',([37,39,41],['MPL_60_036-070_transcription.tex:20,42–46,76–89']),r'pas local',
'The global-constituent semisimplification proposal is rejected because it is not local and lacks the desired étale compatibility; the next pages replace it by a local construction using normal unipotent inertia.','The page supplies the rejection but not a worked global counterexample. No such example is falsely attributed to the author.','agrees','The rejection precedes the new local construction.',[(2,1,'kept','Scan37 expressly abandons the global recipe; the new D/I construction begins on39 and is not the same operation.')])
add(450,'Additive local averaging after unipotent dévissage','other',([39,41,43,45,47],['MPL_60_036-070_transcription.tex:42–46,76–89,116–122,146–163,195–211']),r'U\triangleleft D',
'Let I◁D and U◁D be finite-index inI; over a characteristic-zero field assume U acts unipotently onV. A D-stable filtration with U-trivial graded factors defines [V] in K₀(Rep(D/U)); exact finite-group I/U invariants give V^♮ in K₀(Rep(D/I)). The class is independent of shrinkingU, additive, and invariant under changing Frobenius lifts.','Frobenius-lift invariance follows from the D-stable filtration; averaging arbitrary unfiltered traces without the U hypothesis is not a proof. “restr” between quotient categories is interpreted as inflation.','agrees','The hypotheses and filtration mechanism occur on39–47, and the note does not discard them.',[(2,2,'kept','The exact averaging argument uses characteristic0, a D-normal subgroupU and its unipotent action, all present on39–41.'),(2,4,'merged','The trace-average proof on45–47 uses the same filtration and supplies lift independence for that construction.')])
add(451,'Averaging is additive but not tensor compatible','unpursued implication',([41,45],['MPL_60_036-070_transcription.tex:76–89,146–163']),r'\frac1N\sum',
'Finite-group invariants are exact in characteristic0 but need not preserve tensor products. For the nontrivial sign representation s ofC₂, s^{C₂}=0 while (s⊗s)^{C₂}=1.','The counterexample tests an inference not made in the text; no tensor-functor claim is attributed to the author.','agrees','The note correctly bounds the additive construction.',[(2,3,'kept','The manuscript claims additive averaging; the C₂ test prevents the earlier interpretation from silently strengthening it to a tensor functor.')])
add(452,'Collision of Eη(x) notation','reading question',([47,49,51],['MPL_60_036-070_transcription.tex:199–211,260–266,289–299']),r'E_\eta(x)=E_\eta^\natural(x)',
'On47 Eη(x) is identified with the averaged class; on51 α is defined as the difference between E^♮ and Eη(x), where the subsequent formulas require ordinary inertia invariants. Read literally with47, α would be zero by definition.','Use separate symbols V^♮ and V^I in the mathematical reconstruction. This is not an ink correction.','agrees','The two usages are textually incompatible unless distinguished.',[(2,5,'kept','The note locates the exact notation collision on47/51; ordinary invariants are required for the defect formula, but the scans must decide the notation.')])
add(453,'The additive local μ cancels in the stated category','unpursued implication',([49,51,55],['MPL_60_036-070_transcription.tex:260–266,289–328,431–456']),r'\mu(E)=\alpha(E)^\vee-\alpha(\check E)(1)',
'After separating ordinary invariants from averaging, α(V)=[V^♮]−[V^I] is generally nonadditive. In the usual quasi-unipotent ℓ-adic local category, the displayed additive μ vanishes in K₀: dévissage reduces to U-trivial factors, where α=0, or the monodromy exact sequence cancels the two terms directly.','This is an independent consequence of the manuscript’s stated additivity and local hypotheses; the author does not explicitly withdraw μ on these pages. A tame length-two Jordan block checks the cancellation and the nonadditivity of α.','agrees','The earlier note labels the cancellation as a consequence, not an explicit sentence of the author.',[(2,7,'kept','The local μ formula and asserted additivity on51 force cancellation under the normal-unipotent dévissage already proved on39–43.'),(2,8,'merged','The Jordan-block calculation tests that exact cancellation while retaining the nonzero α defect.')])
add(454,'Dropped local Tate factors','reading question',([53,55],['MPL_60_036-070_transcription.tex:363–404,431–447']),r'L_{\alpha(\check E)}(p^{-1}t)',
'From μ=α(E)^∨−α(E^∨)(1), L_μ(t)=L_{α(E)^∨}(t)/L_{α(E^∨)}(p^{-1}t). If E^∨≃E(ρ), the denominator becomes L_{α(E)}(p^{-(ρ+1)}t). The next displayed denominators lose the required twist.','The first occurrence with p^{-1} fixes the convention; retain all versions diplomatically until checked on scans.','agrees','The inconsistency is algebraic within the supplied formulas.',[(2,10,'kept','The note correctly compares the local denominator on53 to the immediately preceding μ identity; the missing shift is not explained by the fixed geometric-Frobenius convention.')])
add(455,'Modified Euler characteristic and conductor formula','self-flagged step',([55,59],['MPL_60_036-070_transcription.tex:450–456,538']),r'calculer \chi',
'For smooth proper connected curveX, openU, lisse rankr V and j:U→X, χ^♮=rχ_c(U)−Σ_x deg(x)Swan_x(V)+Σ_{x∈X minus U}deg(x)dim(V_x^♮). This is GOS plus the finite-support correction defining the modified extension.','Residue degrees and geometric Euler characteristics are explicit. The Artin conductor form is equivalent after adding ordinary inertia invariants.','agrees','The author asks for χ on55 and points to Artin representations on59.',[(2,11,'kept','The modified χ problem is explicit; the note’s formula combines the declared extension with the GOS theorem rather than claiming a proof on the page.')])
add(456,'Squared determinant reduction and the unresolved sign','self-flagged step',([53,57,59],['MPL_60_036-070_transcription.tex:385–404,493–520,538']),r'modulo un signe',
'The determinant duality gives a square relation for the normalized global determinant in terms of local defects. Taking a square root determines it only up to sign. One intermediate equation on57 drops a factor, whereas the subsequent normalized formula is algebraically consistent.','In the category where μ=0 the corrected relation simplifies, but it still does not supply the root sign. The two χ symbols on57 (global and sum of local ranks) must be distinguished.','agrees','The note follows the question mark on53 to the local product and the explicit sign warning on59.',[(2,13,'kept','The question on53 is answered only by a squared local-product relation on57, with the square-root sign left open.'),(2,14,'merged','The inconsistent intermediate equality on57 is part of that same determinant calculation and is an ink alarm, not another theorem.')])
add(457,'Splitting the local factor loses visible additivity','self-flagged step',([55],['MPL_60_036-070_transcription.tex:431–456']),r'additivité',
'Writing an additive μ-factor as a quotient of α-factors can obscure cancellation because α is not additive. The author explicitly warns about this loss of additivity.','This warning coheres with the vanishing calculation of SA14-453; it does not prove each α-factor separately additive.','agrees','The note records a written caution rather than inferring a new unresolved theorem.',[(2,15,'kept','The warning on55 is retained with its exact logical target: splitting an additive expression into nonadditive pieces.')])
add(458,'Local-to-global determinant and epsilon factors','self-flagged step',([55,57,59],['MPL_60_036-070_transcription.tex:450–456,493–520,538']),r'\delta',
'The author asks for the global determinant from local data. Later local epsilon theories and Laumon’s product formula solve a precise curve version using a nontrivial additive character and a nonzero meromorphic1-form, with measure/Frobenius conventions fixed.','Those extra choices are not specified on these pages. The theorem is compared after translating conventions, not substituted literally for the manuscript’s incomplete recipe.','agrees','The note correctly distinguishes the sign-sensitive product theorem from the squared relation already on57.',[(2,16,'kept','Problem055(c) and the “modulo un signe” reduction point to the later epsilon-factor product problem; the note preserves the extra data needed by that theorem.')])
add(459,'Strict lower-niveau normalization','self-flagged step',([63,65,67,69],['MPL_60_036-070_transcription.tex:593–624,659–679,721–745,775–791']),r'niveau strictement plus petit',
'Given σ(t)=1/(qt), the author seeks λ built from lower-level factors so that σ(λL)/(λL) is a constant sign. The unrestricted solution λ=1/L is explicitly inadequate to this constraint. The initial root-weight-range wording is cancelled and replaced by structured factors.','If a precise σ-stable multiplicative subgroupH of allowed factors were supplied, an H¹(C₂,H) obstruction and fixed-point order parity would be valid modern reformulations. The packet does not define H sufficiently to identify a unique modern theorem.','agrees','The strict restriction and revision of wording are visible; the notes correctly reject unrestricted Hilbert90 as a solution.',[(2,19,'kept','The trivial inverse solution does not respect the stated smaller-niveau requirement on65.'),(2,20,'merged','The subgroup/cohomology formulation is a conditional reconstruction of the same restriction, requiring σ-stability not given by name alone.'),(2,21,'merged','Fixed-point parity is a concrete necessary test for any specified restriction, not a solution of the undefined full problem.'),(2,58,'merged','The cancelled weight-range formulation and its structured replacement are the same problem’s revision history.')])
add(460,'Haar measure construction on reused sheets','other',([4,6,8,10],['MPL_60_002-035_transcription.tex:68–89,138–160,195–213,258–283']),r'(f:g)',
'For a locally compact group, nonnegative compactly supported continuous functions are dominated by finite positive sums of translates. The resulting covering ratios, normalized at a fixed nonzero function, have uniform approximate additivity; a common ultrafilter yields a positive invariant functional and hence Haar measure. Uniqueness is referred elsewhere.','For f=0 the nonemptiness witness must still obey the stipulated nonzero positive measure; in the positivity line the vanishing criterion is μ=0 OR f=0, not AND. These are literal printed/text alarms, not handwriting claims.','agrees','The note separates the ratio construction and two local defects from the unavailable uniqueness chapter.',[(1,69,'kept','All four reused Haar fragments were read in their reversed order; the note’s nonzero-witness and “et/ou” corrections are supported by the displayed definitions.')],attribution='reused printed Bourbaki integration draft')
add(461,'Symbolic-power degree is not colength','reading question',([24,30],['MPL_60_002-035_transcription.tex:642–662,831–838']),r'deg Q',
'The literal degree definition using the leastm with p^(m)⊂Q is not equal to length(C_p/Q_p) in a one-dimensional nonnormal order. The cusp C=k[[t²,t³]], Q=t⁴C has leastm3 but colength4, although Q is principal. Therefore the associated length/normalization criterion needs the length definition or extra hypotheses.','A=k[[t²]], B=k[[t]] satisfy the finite normalization setup for char(k)≠2. A proposed avoiding-generator criterion also fails with a=(t²,t³), y=t³.','agrees','The note’s mathematical alarm is valid under the printed hypotheses; no source correction is made.',[(1,71,'kept','The grouped entry correctly separates height preservation from the defective degree definition; the explicit cusp checks the normal-base and finite-normalization hypotheses.')],attribution='reused printed commutative-algebra exercises')
add(462,'Trace duals, differents, socles and Gorenstein orders','other',([20,22,24],['MPL_60_002-035_transcription.tex:540–558,598–610,642–662']),r'C^*',
'For finite orders in a finite separable extension of the fraction field of a normal Noetherian domain, the trace dual is a full lattice. The conductor/different and invertible-dual criteria are codimension-one statements. The irreducible-primary/socle criterion is local at the supporting prime; its global literal form fails. Quadratic orders are Gorenstein; requiring every order in a number field to be Gorenstein forces degree≤2.','Separability is essential for the trace-lattice argument. Localize the socle and colon identities; do not identify global k[y] with a simple module at the prime(x) ofk[x,y]. Distinct exercises are split into claim records.','agrees','The note item groups many exercises; those obligations are retained individually in the claims map.',[(1,72,'kept','Every subexercise in the grouped trace/different entry was checked against its printed occurrence; the missing separability and localization conditions are preserved as explicit alarms.')],attribution='reused printed commutative-algebra exercises')
add(463,'Divisor-valued Euler characteristics','other',([28],['MPL_60_002-035_transcription.tex:772–788']),r'\chi',
'For finite torsion modules over a Noetherian normal domain, χ(M)=Σ_htp=1 length(M_p)[p] is additive on exact sequences, invariant under pseudo-isomorphism, and vanishes precisely for pseudo-null modules. The alternating sum vanishes for finite exact complexes.','The following Proposition11 is cut after its first listed condition; its full equivalence cannot be reconstructed.','agrees','The note correctly distinguishes complete identities from the truncated proposition.',[(1,73,'kept','The divisor-length arguments are complete enough to identify, but the final cut proposition has no supplied conclusion to verify.')],attribution='reused printed commutative-algebra text')
add(464,'Exterior powers, Fitting data and flatness exercises','other',([32,34],['MPL_60_002-035_transcription.tex:860–874,917–937']),r'\Lambda^rE',
'The local finite-module exercises relate exterior annihilators, invariant factors and flatness; the relative Fitting divisors of two full lattices are signed. For an injection of rankr torsion-free modules, the codimension-one length of its kth exterior-power cokernel is binom(r−1,k−1) times the original length.','Missing local antecedents cannot be silently restored. The relative-divisor monotonicity needs lattice containment; exterior-index endpoints require correction on the scans. Separate exact computations appear in the claims map.','agrees','The grouped note identifies both valid identities and literal scope/index defects.',[(1,74,'kept','The Fitting, exterior and flatness obligations were read individually; the relative-lattice monotonicity and truncated local assumptions are not accepted without qualification.')],attribution='reused printed commutative-algebra exercises')
add(465,'Titles, rédaction reports and dating limits','title, date or page count',([2,14,18],['MPL_60_002-035_transcription.tex:2–6,398–419,489–508']),r'Notes sur l’équation fonctionnelle',
'The cover titles the handwritten work on functional equations. Reused printed sheets carry Bourbaki reports and assignments referring to1962/1963; published chapter dates are bibliographic facts distinct from the date of the handwriting.','No manuscript date is inferred solely from reused stationery. Editorial jokes and rejected chapter proposals are retained as archival evidence, not mathematical theorems.','agrees','The notes correctly distinguish cover title, printed report content and uncertain handwriting chronology.',[(1,75,'kept','The cover and rédaction reports are directly present; their printed dates cannot date the later handwriting without independent evidence.')],attribution='cover and reused printed Bourbaki editorial reports')
add(466,'Ancillary exercise obligations separated in the claims map','other',([20,22,24,26,30,32,34],['MPL_60_002-035_transcription.tex:540–558,598–610,642–662,712–733,831–838,860–874,917–937']),r'Exercices',
'The additional obligations include injectivity, different/ramification tests, finite-field monogeneity, exactness of divisorial χ, Fitting examples and exterior formulas. Each distinct assertion receives a separate claim record with attribution to the reused text.','This source entry is a multi-topic checklist; it has one verdict and one item while its mathematical subclaims are linked separately, avoiding duplicate entry accounting.','agrees','The additional checklist is supported by actual passages, but cannot replace their individual mathematical checks.',[(1,76,'kept','All additional RT47–RT64 obligations are retained and split at claim level; the checklist itself receives one source-entry verdict.')],attribution='earlier-run checklist of reused printed exercises')
add(467,'Bass bibliographic lead','idea of the earlier run',([22,24],['MPL_60_002-035_transcription.tex:598–610,642–662']),r'C^*',
'Bass’s1963 Gorenstein paper is a genuine bibliographic lead for the order criteria, but the direct DOI request failed in this run. A primary later paper by Marseglia was opened and used for the exact trace-dual/Bass characterization.','Bass is not marked verified on the strength of memory or another paper’s bibliography. The item’s bibliographic status is distinct from independently checked mathematical cases.','agrees','The note explicitly withheld verification and that caution remains warranted for the failed endpoint.',[(1,77,'kept','The DOI identifies a real bibliographic lead, but the opened later source does not make the inaccessible Bass text an independently checked endpoint.')],attribution='earlier-run bibliography; Bass endpoint unavailable in this run')
add(468,'Finite-field monogeneity obstruction and cyclotomic realization','other',([20,62],['MPL_60_002-035_transcription.tex:554–558','MPL_60_036-070_transcription.tex:584']),r'[L:\mathbf Q]=3',
'A split residue algebra k^n is generated by one element overk exactly when k has at leastn elements. For the cubic subfieldL⊂Q(ζ₃₁),2 splits completely, so the normalization of Z_(2) inL has residue F₂³ and cannot be monogenic.','The cross-reference to an earlier cote is quarantined; the two cote60 printed endpoints are present and checked.','agrees','The local criterion and concrete cyclotomic hint match exactly.',[(1,64,'kept','The claimed cross-packet addition is concretely supported by20 and62 within the supplied cote; the external packet itself remains unavailable.'),(2,37,'merged','The order of2 modulo31 gives the split cubic residue algebra, realizing the finite-field obstruction stated on20.')],attribution='reused printed algebra exercises and earlier-run cross-reference')
add(469,'Hensel factorization needs coprime reductions','reading question',([38],['MPL_60_036-070_transcription.tex:33']),r'P=QR',
'A complete local-ring Hensel factorization lifts a prescribed factorization of a monic polynomial when the residue factors are coprime. Without that condition, X²−p overZ_p reduces toX·X but has no degree-one factor inZ_p[X].','The displayed hypotheses, including splitting over an algebraic extension, do not rescue the literal statement. Coprimality is the scan alternative to test.','agrees','The counterexample satisfies completeness and the printed factorization hypotheses.',[(2,23,'kept','The literal printed Hensel statement lacks coprimality; the valuation of a hypothetical square root ofp contradicts integrality.')],attribution='reused printed commutative-algebra exercise')
add(470,'Quotient Fitting inclusion is reversed','reading question',([64],['MPL_60_036-070_transcription.tex:648']),r'\mathfrak f_k(M/N)\subset\mathfrak f_k(M)',
'For a surjectionM→M/N, Fitt_k(M)⊂Fitt_k(M/N). The opposite inclusion in the transcript fails forM=A andN=aA: Fitt₀(A)=0 while Fitt₀(A/aA)=(a).','The succeeding convolution inclusion for an extension is a different statement and is not reversed by this correction.','agrees','The elementary cyclic example fixes the direction without any convention ambiguity.',[(2,24,'kept','The note’s reversed-inclusion alarm is confirmed by the standard cyclic presentation and the preceding minors definition.')],attribution='reused printed commutative-algebra exercise')
add(471,'Fitting ideals and annihilators','other',([64],['MPL_60_036-070_transcription.tex:632–650']),r'\mathfrak f_k(M)',
'For a finite presentation, minors define presentation-independent Fitting ideals. They commute with base change, increase withk, satisfy Fitt₀⊂Ann(M) and Ann(M)^r⊂Fitt₀ forr generators, and satisfy the direct-sum convolution formula. Over a PID they recover the ordered invariant factors.','The external annihilator outline is not supplied; the current exercise gives an exact algebraic formulation independently of it.','agrees','The claims are visible on64 and are separated from its wrong quotient inclusion.',[(2,25,'kept','The note’s positive Fitting comparison is supported by the full minors exercise; the separate reversed inclusion remains SA14-470.')],attribution='reused printed commutative-algebra exercise')
add(472,'Local versus global number of generators','other',([64],['MPL_60_036-070_transcription.tex:640–645']),r'r_0\leq r',
'Local Fitting bounds determine the maximum of local minimal generator numbers, which need not equal the global minimum. A nonprincipal invertible ideal ofZ[√−5], such as(2,1+√−5), is locally cyclic and globally needs two generators.','The example is a reconstruction verifying the strict inequality allowed on the page.','agrees','The exercise allows strict local/global difference; it does not claim a global principal ideal.',[(2,26,'kept','The note correctly reads the inequality rather than an equality; the ideal’s norm2 rules out a principal generator.')],attribution='reused printed commutative-algebra exercise')
add(473,'Saturated free submodules and nonsplitting','other',([50,64],['MPL_60_036-070_transcription.tex:273–283,630']),r'(-Y,X)',
'Overk[X,Y], the injectionA→A² by(-Y,X) has torsion-free quotient(X,Y), which is not reflexive and not projective at(X,Y). Thus a saturated rank-one free submodule need not split.','This simultaneously checks the explicit quotient exercise and bounds the primitive-vector/rank-reduction lemma.','agrees','The free-kernel example and the rank-reduction context agree.',[(2,27,'kept','The displayed quotient on64 identifies the maximal ideal(X,Y), giving the promised torsion-free nonreflexive module.'),(2,55,'merged','The same sequence shows why the saturated line obtained in rank reduction need not have a global complement.')],attribution='reused printed commutative-algebra text and exercise')
add(474,'Hom–Ext reflexivity criterion needs E nonzero','reading question',([68],['MPL_60_036-070_transcription.tex:755']),r'Hom(E,F)',
'The proposed implication from Hom(E,F) reflexive and Ext¹(E,F)=0 toF reflexive requires a nonzero finite torsion-free sourceE. IfE=0 all premises hold for everyF, including a nonreflexive or torsion module.','The nonzero-source alternative is suggested mathematically; the full corrected theorem is checked separately under its ambient normal-domain hypotheses.','agrees','The zero-source counterexample respects the literal finite torsion-free premise.',[(2,28,'kept','The entry identifies an actual omitted edge case: the zero module makes both Hom and Ext hypotheses vacuous.')],attribution='reused printed commutative-algebra exercise')
add(475,'Finite intersections and two free lattices','other',([68],['MPL_60_036-070_transcription.tex:753,761']),r'\bigcap M_\lambda',
'A nonempty family of full reflexive lattices in a finite-dimensional fraction-field vector space, all containing a fixed full lattice, has reflexive intersection determined by finitely many members. A reflexive lattice contained in a free latticeL can be written L∩L₁ for a suitable free fractional latticeL₁.','The first finite witness follows by summing the dual lattices inside a fixed finite module. The second needs the height-one approximation argument supplied in the proof notes, not merely Noetherianity of descending chains.','agrees','Both exercises are present and the note correctly separates the two mechanisms.',[(2,29,'kept','The bounded-intersection statement uses ascending sums of duals; the common full lattice is essential.'),(2,59,'merged','The two-free-lattice representation is a stronger finite-data result on the same page, retained as its own claim under this lattice item.')],attribution='reused printed commutative-algebra exercises')
add(476,'Veronese extension: torsion and intersection failure','other',([40,66],['MPL_60_036-070_transcription.tex:71,685–689']),r'k[X^2,XY,Y^2]',
'ForA=k[X²,XY,Y²]⊂B=k[X,Y] andp=(X²,XY), the tensor map p⊗_A B→pB has nonzero kernelB/(X,Y). The idealpB=X(X,Y) is not divisorial, while its reflexive hull isXB. Extension therefore need not preserve reflexivity or intersections without flatness.','A is normal; B is finite overA, but not flat. Flat extensions of Noetherian domains preserve reflexivity by the separate standard theorem.','agrees','The note’s explicit tensor defect and the older intersection example concern the same extension.',[(2,30,'kept','The syzygy presentation gives the exact torsion kernelB/(X,Y), stronger than merely saying nonflat.'),(2,31,'merged','The contrast with flat base change is necessary: finite extension alone does not preserve reflexivity in this same example.'),(2,46,'merged','The field-intersection example on40 and tensor example on66 identify the same Veronese ring; they are not unrelated pathologies.')],attribution='reused printed commutative-algebra exercises')
add(477,'Restriction of scalars and reflexive lattices','other',([58,60],['MPL_60_036-070_transcription.tex:528–534,544–550']),r'(R_A)_{\mathfrak p}=\bigcap R_{\mathfrak P}',
'For a finite extension of Noetherian normal domainsA⊂B with fraction fieldsK⊂L, a finite torsion-freeB-module is reflexive overB iff its restriction is reflexive overA. The proof groups height-one localizations over each base prime.','This is restriction of scalars, an exact functor; it is not a claim that tensor extension is flat.','agrees','The printed proof uses the height-one intersection formula, not a tensor-exactness assertion.',[(2,32,'kept','The note correctly attributes the reflexivity equivalence to restriction and the finite normal extension hypotheses.')],attribution='reused printed commutative-algebra text')
add(478,'Base change modulo pseudo-null defects','other',([54,56],['MPL_60_036-070_transcription.tex:411–426,468–489']),r'pseudo-isomorphisme',
'Under a finite extension of Noetherian normal domains, tensoring an injection can create a kernel, but localizing at height-one primes ofB makes the relevant base algebra free over the DVR ofA. The kernel is pseudo-null and divisorial invariants behave as specified.','The assertion is exact only in the quotient by modules supported in codimension≥2; the Veronese example shows that this qualification cannot be removed.','agrees','The print proof explicitly passes through height-one localizations.',[(2,33,'kept','The note accurately retains the pseudo-null qualification instead of claiming ordinary exactness after finite base change.')],attribution='reused printed commutative-algebra text')
add(479,'Divisor pullback, norm and restriction formula','other',([52,54,56,58,60],['MPL_60_036-070_transcription.tex:336–347,411–426,468–489,526–534,544–550']),r'e(\mathfrak P/\mathfrak p)',
'Divisor extension multiplies by ramification indicese(P/p), while the norm multiplies by residue degreesf(P/p). Both are transitive. For finite torsion-freeB-moduleM, rank_A M=[L:K]rank_B M and c_A(M)=N c_B(M)+rank_B(M)c_A(B).','The formulas live in divisor/class groups with the text’s sign convention; equalities of unreflexified ideals are not inferred.','agrees','Both directions and the extra c_A(B) term are visible across the reused fragments.',[(2,34,'kept','The note correctly distinguishes ramification-weighted pullback from residue-degree-weighted norm and preserves the restriction correction term.')],attribution='reused printed commutative-algebra text')
add(480,'Evaluation map and projectivity','other',([66],['MPL_60_036-070_transcription.tex:693']),r'E^*\otimes E\longrightarrow End(E)',
'For a finite torsion-free moduleE over a Noetherian normal domain, evaluationE^*⊗E→End(E) is a pseudo-isomorphism. Its source is reflexive exactly whenE is projective: then the map is an isomorphism; conversely its surjectivity gives a finite dual basis.','Retain the ambient finiteness and torsion-free hypotheses from the printed section; reflexivity is the asserted property of the evaluation source.','agrees','The note identifies the projectivity criterion rather than treating pseudo-isomorphism as automatic ordinary isomorphism.',[(2,35,'kept','The displayed evaluation map becomes an actual isomorphism under reflexivity of both sides, and the identity endomorphism yields the required dual basis.')],attribution='reused printed commutative-algebra exercise')
add(481,'Tor–Ext corrections in divisor identities','other',([66],['MPL_60_036-070_transcription.tex:699–716']),r'Tor_1, Ext^1',
'At height-one DVRs, Tor_i and Ext^i vanish fori≥2; Tor₁ and Ext¹ also vanish when the first finite module is torsion-free. The printed tensor/Hom divisor formulas include Tor₁/Ext¹ precisely to account for torsion lengths.','The Tor₁ term cannot be deleted for arbitrary modules. A/π^a againstA^r⊕A/π^b provides exact min(a,b) length tests.','agrees','The notes retain the correction terms required by the local computations.',[(2,36,'kept','The note matches the printed formulas and checks them on torsion DVR modules, where omitting Tor or Ext gives the wrong divisor.')],attribution='reused printed commutative-algebra exercises')
add(482,'Cyclic differentials without a power basis','other',([62],['MPL_60_036-070_transcription.tex:586']),r'\Omega_{B/A}=B\,dx',
'For the stated finite separable extension of Dedekind domains with separable residue extensions, Ω_{B/A} is cyclic and generated bydx for a suitablex. This does not implyB=A[x]; the split cubic residue obstruction supplies a counterexample to that implication.','The generation by a single differential is tested under the separable-residue hypotheses; it is not a universal statement for arbitrary finite extensions.','agrees','The exercise asks for cyclic differentials, separately from the preceding nonmonogeneity example.',[(2,38,'kept','The two adjacent exercises intentionally distinguish a differential generator from an algebra generator; the note preserves that distinction.')],attribution='reused printed commutative-algebra exercise')
add(483,'Non-simple purely inseparable residue in a separable extension','other',([62],['MPL_60_036-070_transcription.tex:588']),r'radicielle',
'In characteristicp, letk=F_p(s,t),A=k[[π]], and B=A[α,β] withα^p−πα=s, β^p−πβ=t. This is a finite free local DVR extension with separable fraction-field extension, residuek(s^{1/p},t^{1/p}), and Ω_{B/A}≃(B/π)², so its differentials are not cyclic.','This explicit construction supplies the requested example; the residue extension has exponent1 and degreep² and hence is not simple.','agrees','The note’s example meets completeness, separability of fractions and nonsimplicity of residue simultaneously.',[(2,39,'kept','The two derivative equations give πdα=πdβ=0; the field and residue hypotheses are checked rather than inferred from the word radicial.')],attribution='reused printed commutative-algebra exercise; example reconstructed in notes')
add(484,'Pseudo-null versus zero','other',([46,68],['MPL_60_036-070_transcription.tex:178–190,767–769']),r'pseudo-nul',
'A finite pseudo-null module over a Dedekind domain is zero. Over a higher-dimensional normal domain it can be nonzero; k[X,Y]/(X,Y) is a basic example, and the printed intersection/module examples exhibit such codimension-two defects.','Codimension one is the exact boundary of this simplification.','agrees','The note correctly restricts pseudo-isomorphism= isomorphism to the Dedekind setting.',[(2,40,'kept','The Dedekind simplification on46 is valid; the explicit higher-dimensional defects later in the packet show why it cannot be generalized.')],attribution='reused printed commutative-algebra text and exercises')
add(485,'Torsion decomposition need not split globally','other',([68],['MPL_60_036-070_transcription.tex:765–769']),r'A/(XY)',
'The torsion quotient in the displayed rank-two example is not a direct summand; A/(XY) does not split asA/(X)⊕A/(Y), and the failure of ideal-intersection action onM=A/(X−Y) is a nonzero codimension-two quotient.','These are module statements over a normal ring of dimension2, not counterexamples to primary decomposition of ideals or DVR structure.','agrees','The note separates nonsplitting from codimension-one decomposition.',[(2,41,'kept','The three examples on68 each concern a genuine global module defect; they do not contradict the height-one classification used earlier.')],attribution='reused printed commutative-algebra exercises')
add(486,'Unit-ideal certificate needs vertical primes','other',([70],['MPL_60_036-070_transcription.tex:795–800']),r'1\in\mathfrak a',
'If an idealI of a polynomial ring over a UFD becomes the unit ideal over the fraction field, clearing denominators gives0≠d∈I. Checking I+(p)=B for each primep dividingd then provesI=B. A fraction-field calculation alone does not.','The gcd normalization must come with a certificate; it is not a replacement for the vertical residue checks.','agrees','The printed finite procedure has both generic and residue steps.',[(2,42,'kept','The note correctly retains the finitely many vertical checks after clearing a denominator; an ideal(p,X) shows why the generic test alone fails.')],attribution='reused printed commutative-algebra exercise')
add(487,'Factoriality exercises and base-change limits','other',([40,42,44],['MPL_60_036-070_transcription.tex:53–71,97–111,129–141']),r'factoriel',
'The printed exercises range from UFD failures under formal power series, completion and field extension to positive criteria for quadrics, cyclic weighted hypersurfaces, Prüfer rings and formal power series over a PID. These have distinct hypotheses and are separated in the claims map.','The circle and anisotropic conic examples show that factoriality is not invariant under arbitrary field extension. Missing antecedents of the formal-series construction are recorded, not guessed.','agrees','The note’s broad warning is supported, but no single factoriality theorem subsumes every exercise.',[(2,43,'kept','All relevant printed factoriality exercises were read; the item summarizes them while their individual hypotheses and literature fates are recorded at claim level.')],attribution='reused printed commutative-algebra exercises')
add(488,'Characteristic-two derivations and infinite class groups','other',([36],['MPL_60_036-070_transcription.tex:5–15']),r'\Delta(X)=Y^{2j},\quad\Delta(Y)=X^{2i}',
'For the characteristic2 derivationΔ=Y^{2j}∂_X+X^{2i}∂_Y ofk[[X,Y]], its invariant ring is described byU=X²,V=Y²,Z=X^{2i+1}+Y^{2j+1} withZ²=U^{2i+1}+V^{2j+1}. The exercise relates logarithmic derivatives to divisor classes and gives a subgroupk^{N(i,j)}.','The preceding cut derivation example and undefined logarithmic-derivative group cannot be reconstructed uniquely. The lattice-point count and the casei=j=2 are checked; the full class-group statement is compared to the primary derivation literature with its hypotheses.','agrees','The note correctly separates the count from the required class-group argument.',[(2,44,'kept','The invariant-ring formulas and count are present on36, but the full class-group proof and cut antecedent require the separately documented literature match.')],attribution='reused printed commutative-algebra exercise')
add(489,'Completed cyclic group algebra','other',([38],['MPL_60_036-070_transcription.tex:31']),r'\gamma_n(T)=1-(1-T)^{p^n}',
'For a complete Noetherian local ringA with residue characteristicp, γ_n is distinguished of degreep^n, A[[T]]/(γ_n)≃A[Z/p^n], and the compatible quotients recoverA[[T]]. The ideals have zero intersection and tend to0 in the maximal-adic topology.','Zero intersection proves injectivity only; surjectivity uses completeness and the closedness of each principal ideal.','agrees','The note identifies the completed-group-ring construction while retaining the needed topology argument.',[(2,45,'kept','The formulas on38 support the inverse limit, but the proof must use completeness in addition to the displayed zero-intersection claim.')],attribution='reused printed commutative-algebra exercise')
add(490,'Dual notation across unrelated categories','idea of the earlier run',([9,16,49,51],['MPL_60_002-035_transcription.tex:216–243,463–470','MPL_60_036-070_transcription.tex:233–328']),r'\check E',
'Contragredient ℓ-adic representations, Verdier dual complexes, finite-length Hom(-,K/A), Cartier dual group schemes and polarized abelian-variety duals are distinct operations. Their notation alone does not identify them.','The cote60 endpoints are checked. Named external-project identifications remain leads until their own sources are read.','agrees','The contextual note is a warning against a false cross-category merger.',[(2,47,'kept','The notation collision is real, but the note correctly refrains from equating the different dualities across absent project endpoints.')],attribution='earlier-run context comparison')
add(491,'Boundary motive comparison','idea of the earlier run',([25,61],['MPL_60_002-035_transcription.tex:665–698','MPL_60_036-070_transcription.tex:554–578']),r'cohomologie à l’infini',
'Wildeshaus’s boundary motive lies in a motivic triangle ∂M→M→M^c→ and has selfduality with shift2n−1 under the hypotheses of his Theorem6.1. Its realization is a comparison to the boundary formalism, with variance and cone/fiber conventions tracked.','The opened2004/2006 source assumes resolution of singularities in the autoduality section. It is not an unconditional replacement for finite-field ℓ-adic duality nor a proof that the manuscript constructed that motive.','agrees','The note explicitly requires a separate motivic comparison and hypotheses.',[(2,52,'kept','The later boundary-motive theorem has the same characteristic one-unit shift, but its resolution and categorical assumptions are not omitted.')],attribution='earlier-run published comparison')
add(492,'Geometric content beyond averaging','self-flagged step',([55],['MPL_60_036-070_transcription.tex:450–456']),r'valeurs absolues',
'Problem055(a) asks for local α, μ and λ, their characteristic polynomials and absolute values in geometric degenerations. Averaging alone neither describes the monodromy filtration nor determines individual eigenvalues.','Weil–Deligne monodromy and weight theorems answer precise equal-characteristic curve cases; the vague motivic programme is not thereby solved in every possible generality.','agrees','The note correctly distinguishes geometric information from the formal averaging identity.',[(2,53,'kept','The explicit request for eigenvalue absolute values is broader than the construction on39–47 and needs separate monodromy/weight results.')])
add(493,'Avoidance for independent height-one primes','other',([48,52],['MPL_60_036-070_transcription.tex:219–229,353–359']),r'\mathfrak p_i',
'The reduction argument avoids finitely many specified residue obstructions using independence of distinct height-one valuations. The later finite-subset version requires its stated cardinal/translate hypotheses. Distinct height-one primes need not be comaximal and residue fields need not be infinite.','The proof is not ordinary Chinese remainder for arbitrary ideals. The missing continuation is not filled by such a claim.','agrees','The note identifies the exact limitations of the avoidance step.',[(2,54,'kept','The reused proof uses prime/valuation independence; neither comaximality nor infinite residue fields is assumed on the supplied pages.')],attribution='reused printed commutative-algebra text')
add(494,'Rank reduction and Dedekind splitting','other',([46,48,50],['MPL_60_036-070_transcription.tex:170–190,219–229,273–283']),r'rang\geq2',
'For a finite torsion-free module over a Noetherian normal domain, the primitive-vector construction produces a free rank-one submodule with torsion-free quotient when rank≥2. Induction ends in an ideal. Over a Dedekind domain that ideal is projective, so the successive extensions split.','The split conclusion depends on Dedekind projectivity; it does not hold globally over every higher-dimensional normal domain.','agrees','The note correctly reads the reduction and its distinct Dedekind conclusion.',[(2,56,'kept','The argument reduces rank while preserving torsion-freeness; only the Dedekind step supplies the complement needed for a direct-sum classification.')],attribution='reused printed commutative-algebra text')
add(495,'Missing internal page4–39','title, date or page count',([52],['MPL_60_036-070_transcription.tex:353–359']),r'4–39',
'The supplied reused reduction proof jumps past an internal printed page4–39. The statement visible before the cut can be recorded, but the absent portion of its proof is not checked.','This is a source-boundary record, not evidence that the theorem is false or unfinished in the published chapter.','agrees','The note distinguishes an incomplete archival fragment from a mathematical failure.',[(2,60,'kept','The continuation is absent from this package; its missing text cannot be reconstructed by treating nearby lemmas as the omitted proof.')],attribution='reused printed text: incomplete fragment')
# Substantive refinement following the trace/conductor re-proof.
for item in ITEMS:
    if item['id']=='SA14-462':
        item['check']='understates'
        item['check_reason']='The note correctly separates the exercises but overlooks a further global biduality defect: the printed order C need not be reflexive over A.'
        item['statement'] += ' The global identity C:B=B*:C* fails for nonreflexive C; it is valid after localization at height one, or with C=C**. The example A=Q[x,y], B=Q(sqrt(2))[x,y], C=A+(x,y)sqrt(2) has C:B=(x,y)B while B*:C*=B.'
        item['reconstruction'] += ' This additional counterexample is ours; it satisfies all finite, normal-base, separable-fraction-field hypotheses.'
for entry in ENTRIES:
    if entry['entry_id']=='MPL_60_002-035#72':
        entry['verdict']='corrected'
        entry['reason']='Retain the trace, different and local Gorenstein discussion, but replace the unqualified global biduality argument: C need not be reflexive. A=Q[x,y], B=Q(sqrt(2))[x,y], C=A+(x,y)sqrt(2) gives C:B=(x,y)B and B*:C*=B. The height-one identity remains valid.'
def save():
    ROOT.mkdir(parents=True,exist_ok=True)
    (ROOT/'items.json').write_text(json.dumps(ITEMS,ensure_ascii=False,indent=2)+'\n')
    with (ROOT/'entries.tsv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['entry_id','item_id','verdict','reason'],delimiter='\t');w.writeheader();w.writerows(ENTRIES)

if __name__=='__main__': save(); print(f'{len(ITEMS)} authored items; {len(ENTRIES)} entries serialized')
